const rows = $input.all().map(r => r.json);
// Assumes rows are in chronological order (oldest to newest)

const current = rows[rows.length - 1];
const previous = rows[rows.length - 2];

const metrics = [
  { label: 'Outgrowers Onboarded', key: 'Outgrowers Onboarded' },
  { label: 'RCN Sold (kg)', key: 'RCN Sold (kg)' },
  { label: 'Revenue (NGN)', key: 'Revenue (NGN)' },
  { label: 'Leads Generated', key: 'Leads Generated' },
  { label: 'Outstanding Debtors (NGN)', key: 'Outstanding Debtors (NGN)' }
];

function pctChange(curr, prev) {
  const c = parseFloat(curr);
  const p = parseFloat(prev);
  if (p === 0) return { pct: null, direction: 'n/a (previous value was 0)' };
  const pct = ((c - p) / p) * 100;
  const direction = pct > 0 ? 'increase' : pct < 0 ? 'decrease' : 'no change';
  return { pct: Math.abs(pct).toFixed(2), direction, raw: pct };
}

function average(values) {
  return values.reduce((a, b) => a + b, 0) / values.length;
}

function stdDev(values) {
  const avg = average(values);
  const variance = average(values.map(v => (v - avg) ** 2));
  return Math.sqrt(variance);
}

function trendStreak(history) {
  let streak = 1;
  let dir = null;
  for (let i = history.length - 1; i > 0; i--) {
    const d = history[i] - history[i - 1];
    const thisDir = d > 0 ? 'up' : d < 0 ? 'down' : 'flat';
    if (dir === null) { dir = thisDir; continue; }
    if (thisDir === dir && thisDir !== 'flat') { streak++; } else { break; }
  }
  return { direction: dir, weeks: streak };
}

// Structured values — this is what the Calculator tool is allowed to combine.
// The AI must not derive these from the text below; it must use these fields directly.
const namedValues = {};

let output = `Legacy Farms — Weekly Sales KPI Report\n`;
output += `Latest Week: ${current['Week']} (compared to ${previous['Week']})\n\n`;
output += `=== LATEST WEEK CHANGE ===\n`;

for (const m of metrics) {
  const prevVal = parseFloat(previous[m.key]);
  const currVal = parseFloat(current[m.key]);
  const { pct, direction } = pctChange(currVal, prevVal);
  output += `${m.label}: ${prevVal} → ${currVal} (${pct !== null ? pct + '% ' + direction : direction})\n`;

  namedValues[m.key] = {
    previous: prevVal,
    current: currVal,
    pctChange: pct,
    direction
  };
}

output += `\n=== PATTERN ANALYSIS (full history, ${rows.length} weeks) ===\n`;

for (const m of metrics) {
  const history = rows.map(r => parseFloat(r[m.key]));
  const avg = average(history);
  const sd = stdDev(history);
  const latest = history[history.length - 1];
  const streak = trendStreak(history);
  const deviationFromAvg = (((latest - avg) / avg) * 100).toFixed(1);
  const isVolatile = sd / avg > 0.3;
  const isOutlier = Math.abs(latest - avg) > 1.5 * sd;

  output += `\n${m.label}:\n`;
  output += `  ${history.length}-week average: ${avg.toFixed(1)}\n`;
  output += `  Trend: ${streak.weeks >= 2 ? `${streak.weeks} consecutive weeks trending ${streak.direction}` : 'no sustained trend'}\n`;
  output += `  Latest week vs average: ${deviationFromAvg > 0 ? '+' : ''}${deviationFromAvg}%\n`;
  if (isVolatile) output += `  ⚠ Volatile: this metric swings more than 30% of its average week to week\n`;
  if (isOutlier) output += `  ⚠ Outlier: latest value is unusually far from its typical range\n`;

  namedValues[m.key].historicalAverage = avg.toFixed(1);
  namedValues[m.key].isVolatile = isVolatile;
  namedValues[m.key].isOutlier = isOutlier;
}

return [{
  json: {
    kpiData: output,      // formatted text for the AI to narrate from
    namedValues           // exact figures — the only inputs the Calculator tool may use
  }
}];
